package com.greenocean.backend.listener.planning;

import jakarta.validation.constraints.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import com.greenocean.backend.listener.live.LiveSupportException;
import java.time.*;
import java.util.*;
import static com.greenocean.backend.listener.planning.ListenerSupportPolicy.*;

@Service @Transactional(noRollbackFor=LiveSupportException.class)
public class ListenerCalendar {
 private final ListenerSupportPolicy p;
 public ListenerCalendar(ListenerSupportPolicy p){this.p=p;}
 public record Settings(@NotBlank @Size(max=80) String timezone,boolean paused,@Min(0)long revision){}
 public record Rule(@NotBlank @Size(max=80) String timezone,@Min(1)@Max(7)int weekday,@NotNull LocalTime startsLocal,@NotNull LocalTime endsLocal,@NotNull LocalDate validFrom,@NotNull LocalDate validUntil,@NotBlank @Pattern(regexp="EARLIER|LATER|BOTH")String overlapPolicy,@Min(0)long revision){}
 public record ExceptionInput(@NotBlank @Size(max=80) String timezone,@NotBlank @Size(max=80) String localStart,@NotBlank @Size(max=80) String localEnd,@Size(max=10) String startOffset,@Size(max=10) String endOffset,boolean available){}
 public record Slot(UUID listenerId,String listenerName,Instant startsAt,Instant endsAt,String timezone,String offset,UUID ruleId,UUID exceptionId){}
 public record Slots(List<Slot> items,boolean hasNext,String nextCursor,Instant serverTime){}
 public ZoneId zone(String value){if(value==null||!ZoneId.getAvailableZoneIds().contains(value)&&!"UTC".equals(value))throw new IllegalArgumentException("Choose a valid IANA timezone");return ZoneId.of(value);}
 public Instant resolve(String local,String zone,String offset){try{var time=LocalDateTime.parse(local);var valid=zone(zone).getRules().getValidOffsets(time);if(valid.isEmpty())throw new IllegalArgumentException("This local time does not exist because of daylight saving");if(valid.size()>1&&offset==null)throw new IllegalArgumentException("Select the explicit offset for the repeated local time");var selected=offset==null?valid.getFirst():ZoneOffset.of(offset);if(!valid.contains(selected))throw new IllegalArgumentException("Offset does not match this local time and timezone");return time.toInstant(selected);}catch(DateTimeException invalid){throw new IllegalArgumentException("Use a valid local date, time and timezone offset");}}
 public Map<String,Object> mine(UUID listener){p.listener(listener);return Map.of("qualified",true,"settings",p.db.queryForList("SELECT timezone,paused,revision FROM listener_calendar_settings WHERE listener_id=?",listener),"rules",p.db.queryForList("SELECT id,timezone,weekday,starts_local,ends_local,valid_from,valid_until,overlap_policy,revision FROM listener_calendar_rules WHERE listener_id=? AND active ORDER BY weekday,starts_local,id LIMIT 50",listener),"exceptions",p.db.queryForList("SELECT id,timezone,starts_at,ends_at,available,revision FROM listener_calendar_exceptions WHERE listener_id=? AND active AND ends_at>listener_support_now() ORDER BY starts_at,id LIMIT 200",listener),"serverTime",p.now());}
 public void settings(UUID listener,Settings in){p.require("SCHEDULE");p.listener(listener);zone(in.timezone());p.lock(listener,listener);p.bound(listener,"CALENDAR_WRITE",30);
  var rows=p.db.queryForList("SELECT revision FROM listener_calendar_settings WHERE listener_id=?",Long.class,listener);if(rows.isEmpty()){if(in.revision()!=0)throw denied(409,"CALENDAR_CHANGED","Reload the calendar settings.");p.db.update("INSERT INTO listener_calendar_settings(listener_id,timezone,paused) VALUES(?,?,?)",listener,in.timezone(),in.paused());}
  else if(p.db.update("UPDATE listener_calendar_settings SET timezone=?,paused=?,revision=revision+1 WHERE listener_id=? AND revision=?",in.timezone(),in.paused(),listener,in.revision())!=1)throw denied(409,"CALENDAR_CHANGED","Reload the calendar settings.");
 }
 @Transactional public UUID rule(UUID listener,UUID id,Rule in){p.require("SCHEDULE");p.listener(listener);zone(in.timezone());if(in.startsLocal().getSecond()!=0||in.startsLocal().getNano()!=0||in.endsLocal().getSecond()!=0||in.endsLocal().getNano()!=0)throw new IllegalArgumentException("Use whole minutes for weekly availability");p.lock(listener,listener);var today=p.now().atZone(zone(in.timezone())).toLocalDate();if(in.validUntil().isBefore(in.validFrom())||in.validUntil().isAfter(in.validFrom().plusDays(366))||in.validUntil().isBefore(today))throw new IllegalArgumentException("Choose a valid future weekly date range up to one year");p.bound(listener,"CALENDAR_WRITE",30);
  if(id!=null){protect(listener,id,null);if(p.db.update("UPDATE listener_calendar_rules SET active=FALSE,revision=revision+1 WHERE id=? AND listener_id=? AND active AND revision=?",id,listener,in.revision())!=1)throw denied(409,"CALENDAR_CHANGED","Weekly rule changed; reload before editing.");}
  if(p.db.queryForObject("SELECT count(*) FROM listener_calendar_rules WHERE listener_id=? AND active",Integer.class,listener)>=p.limits().maxRules())throw denied(409,"CALENDAR_LIMIT","Remove unused weekly rules first.");
  p.db.update("INSERT INTO listener_calendar_settings(listener_id,timezone) VALUES(?,?) ON CONFLICT DO NOTHING",listener,in.timezone());UUID created=UUID.randomUUID();p.db.update("INSERT INTO listener_calendar_rules(id,listener_id,timezone,weekday,starts_local,ends_local,valid_from,valid_until,overlap_policy) VALUES(?,?,?,?,?,?,?,?,?)",created,listener,in.timezone(),in.weekday(),in.startsLocal(),in.endsLocal(),in.validFrom(),in.validUntil(),in.overlapPolicy());return created;
 }
 private void protect(UUID listener,UUID rule,UUID exception){if(p.truth("SELECT EXISTS(SELECT 1 FROM listener_bookings WHERE listener_id=? AND (rule_id=? OR exception_id=?) AND status IN('CONFIRMED','CHECKED_IN','HANDOFF_REQUESTED','ACTIVE') AND reserved_until>listener_support_now())",listener,rule,exception))throw denied(409,"RESERVATIONS_EXIST","Cancel or honor existing reservations before removing this availability.");}
 public UUID exception(UUID listener,ExceptionInput in){p.require("SCHEDULE");p.listener(listener);var start=resolve(in.localStart(),in.timezone(),in.startOffset());var end=resolve(in.localEnd(),in.timezone(),in.endOffset());if(!end.isAfter(start)||!start.isAfter(p.now())||end.isAfter(start.plus(Duration.ofDays(7))))throw new IllegalArgumentException("Choose a future exception lasting at most seven days");p.lock(listener,listener);p.bound(listener,"CALENDAR_WRITE",30);
  if(!in.available()&&p.truth("SELECT EXISTS(SELECT 1 FROM listener_bookings WHERE listener_id=? AND status IN('CONFIRMED','CHECKED_IN','HANDOFF_REQUESTED','ACTIVE') AND tstzrange(starts_at,reserved_until,'[)')&&tstzrange(?::timestamptz,?::timestamptz,'[)'))",listener,date(start),date(end)))throw denied(409,"RESERVATIONS_EXIST","Cancel or honor affected reservations before marking this period unavailable.");
  if(p.db.queryForObject("SELECT count(*) FROM listener_calendar_exceptions WHERE listener_id=? AND active AND ends_at>listener_support_now()",Integer.class,listener)>=p.limits().maxExceptions())throw denied(409,"CALENDAR_LIMIT","Remove unused exceptions first.");UUID id=UUID.randomUUID();p.db.update("INSERT INTO listener_calendar_exceptions(id,listener_id,timezone,starts_at,ends_at,available) VALUES(?,?,?,?,?,?)",id,listener,in.timezone(),date(start),date(end),in.available());return id;
 }
 public void remove(UUID listener,UUID id,boolean exception,long revision){p.require("SCHEDULE");p.listener(listener);p.lock(listener,listener);protect(listener,exception?null:id,exception?id:null);String table=exception?"listener_calendar_exceptions":"listener_calendar_rules";if(p.db.update("UPDATE "+table+" SET active=FALSE,revision=revision+1 WHERE id=? AND listener_id=? AND revision=? AND active",id,listener,revision)!=1)throw denied(409,"CALENDAR_CHANGED","Availability changed; reload before removing it.");}
 public Slots slots(UUID member,UUID listener,int size,String cursor){p.require("BOOKING");p.eligible(member);var now=p.now();var limit=now.plus(Duration.ofDays(p.limits().horizonDays()));var people=p.db.queryForList("SELECT l.user_id,pr.display_name FROM listener_profiles l JOIN profiles pr ON pr.user_id=l.user_id LEFT JOIN listener_calendar_settings s ON s.listener_id=l.user_id WHERE live_listener_qualified(l.user_id) AND l.user_id<>? AND NOT COALESCE(s.paused,FALSE) AND NOT live_pair_blocked(?,l.user_id) AND (?::uuid IS NULL OR l.user_id=?) ORDER BY l.user_id LIMIT 50",member,member,listener,listener);var all=new TreeMap<String,Slot>();
  for(var who:people){UUID target=(UUID)who.get("user_id");String name=(String)who.get("display_name");
   var limits=p.limits();
   var busy=p.db.queryForList("SELECT starts_at,reserved_until AS ends_at FROM listener_bookings WHERE status IN('CONFIRMED','CHECKED_IN','HANDOFF_REQUESTED','ACTIVE') AND (member_id IN(?,?) OR listener_id IN(?,?)) UNION ALL SELECT listener_support_now(),COALESCE(planned_ends_at+(planning_buffer_seconds*INTERVAL '1 second'),admission_until,'9999-12-31'::timestamptz) FROM live_support_requests WHERE status IN('REQUESTED','ACCEPTED','ACTIVE','INTERRUPTED') AND(member_id IN(?,?) OR listener_id IN(?,?)) UNION ALL SELECT starts_at,ends_at FROM listener_calendar_exceptions WHERE listener_id=? AND active AND NOT available UNION ALL SELECT listener_support_now(),allocation_expires_at+((p.planned_seconds+p.handoff_seconds+p.buffer_seconds)*INTERVAL '1 second') FROM listener_wait_queue q CROSS JOIN listener_support_policy p WHERE q.status='OFFERED' AND q.allocation_expires_at>listener_support_now() AND(q.member_id IN(?,?) OR q.listener_id IN(?,?))",member,target,member,target,member,target,member,target,target,member,target,member,target);
   for(var row:p.db.queryForList("SELECT * FROM listener_calendar_rules WHERE listener_id=? AND active ORDER BY id",target)){
    ZoneId z=zone((String)row.get("timezone"));LocalDate from=now.atZone(z).toLocalDate().minusDays(1),until=limit.atZone(z).toLocalDate();LocalDate validFrom=((java.sql.Date)row.get("valid_from")).toLocalDate(),validUntil=((java.sql.Date)row.get("valid_until")).toLocalDate();LocalTime starts=((java.sql.Time)row.get("starts_local")).toLocalTime(),ends=((java.sql.Time)row.get("ends_local")).toLocalTime();
    for(LocalDate day=from;!day.isAfter(until);day=day.plusDays(1)){if(day.isBefore(validFrom)||day.isAfter(validUntil)||day.getDayOfWeek().getValue()!=((Number)row.get("weekday")).intValue())continue;var a=LocalDateTime.of(day,starts);var b=LocalDateTime.of(ends.isAfter(starts)?day:day.plusDays(1),ends);var ao=z.getRules().getValidOffsets(a);var bo=z.getRules().getValidOffsets(b);if(ao.isEmpty()||bo.isEmpty())continue;String overlap=(String)row.get("overlap_policy");addWeekly(all,member,target,name,a,b,z,overlap,(UUID)row.get("id"),now,limit,limits,busy);}
   }
   for(var row:p.db.queryForList("SELECT * FROM listener_calendar_exceptions WHERE listener_id=? AND active AND available AND ends_at>? ORDER BY id",target,date(now)))addWindow(all,member,target,name,instant(row.get("starts_at")),instant(row.get("ends_at")),zone((String)row.get("timezone")),null,(UUID)row.get("id"),now,limit,limits,busy);
  }
  if(cursor!=null){try{String[] bits=cursor.split("\\|",-1);if(bits.length!=2)throw new IllegalArgumentException();Instant.parse(bits[0]);UUID.fromString(bits[1]);}catch(RuntimeException invalid){throw new IllegalArgumentException("Invalid slot cursor");}}
  var values=all.entrySet().stream().filter(e->cursor==null||e.getKey().compareTo(cursor)>0).map(Map.Entry::getValue).toList();boolean more=values.size()>size;var items=List.copyOf(values.subList(0,Math.min(size,values.size())));return new Slots(items,more,more?key(items.getLast().startsAt(),items.getLast().listenerId()):null,now);
 }
 public Map<String,Object> calendars(UUID member,UUID after,int size){p.require("BOOKING");p.eligible(member);var rows=p.db.queryForList("SELECT l.user_id AS id,pr.display_name AS name FROM listener_profiles l JOIN profiles pr ON pr.user_id=l.user_id LEFT JOIN listener_calendar_settings s ON s.listener_id=l.user_id WHERE l.user_id<>? AND live_listener_qualified(l.user_id) AND NOT COALESCE(s.paused,FALSE) AND NOT live_pair_blocked(?,l.user_id) AND(?::uuid IS NULL OR l.user_id>?) AND(EXISTS(SELECT 1 FROM listener_calendar_rules r WHERE r.listener_id=l.user_id AND r.active AND r.valid_until>=listener_support_now()::date) OR EXISTS(SELECT 1 FROM listener_calendar_exceptions e WHERE e.listener_id=l.user_id AND e.active AND e.available AND e.ends_at>listener_support_now())) ORDER BY l.user_id LIMIT ?",member,member,after,after,size+1);boolean more=rows.size()>size;var items=rows.subList(0,Math.min(size,rows.size()));var out=new LinkedHashMap<String,Object>();out.put("items",items);out.put("nextCursor",more?items.getLast().get("id"):null);return out;}
 private void addWeekly(TreeMap<String,Slot> slots,UUID member,UUID listener,String name,LocalDateTime start,LocalDateTime end,ZoneId zone,String overlap,UUID rule,Instant now,Instant horizon,Limits limits,List<Map<String,Object>> busy){
  for(LocalDateTime civil=start;civil.isBefore(end);civil=civil.plusSeconds(limits.slotStepSeconds())){var offsets=zone.getRules().getValidOffsets(civil);if(offsets.isEmpty())continue;var chosen=overlap.equals("BOTH")?offsets:List.of(overlap.equals("LATER")?offsets.getLast():offsets.getFirst());for(var offset:chosen){Instant at=civil.toInstant(offset),finish=at.plusSeconds(limits.plannedSeconds());var localEnd=finish.atZone(zone).toLocalDateTime();if(localEnd.isAfter(end)||localEnd.isBefore(start))continue;var transition=zone.getRules().nextTransition(at);boolean outside=false;while(transition!=null&&transition.getInstant().isBefore(finish)){if(transition.getDateTimeBefore().isAfter(end)||transition.getDateTimeAfter().isBefore(start)){outside=true;break;}transition=zone.getRules().nextTransition(transition.getInstant().plusNanos(1));}if(!outside)addWindow(slots,member,listener,name,at,finish,zone,rule,null,now,horizon,limits,busy);}}
 }
 private String key(Instant start,UUID listener){return new java.time.format.DateTimeFormatterBuilder().appendInstant(9).toFormatter().format(start)+"|"+listener;}
 private void addWindow(TreeMap<String,Slot> slots,UUID member,UUID listener,String name,Instant start,Instant end,ZoneId zone,UUID rule,UUID exception,Instant now,Instant horizon,Limits limits,List<Map<String,Object>> busy){for(Instant at=start;!at.plusSeconds(limits.plannedSeconds()).isAfter(end)&&at.isBefore(horizon);at=at.plusSeconds(limits.slotStepSeconds())){if(at.isBefore(now.plusSeconds(limits.leadSeconds())))continue;Instant finish=at.plusSeconds(limits.plannedSeconds()),reserved=finish.plusSeconds(limits.bufferSeconds()+limits.handoffSeconds());boolean conflict=false;for(var row:busy){Instant a=instant(row.get("starts_at")),b=instant(row.get("ends_at"));if(at.isBefore(b)&&a.isBefore(reserved)){conflict=true;break;}}if(conflict)continue;slots.putIfAbsent(key(at,listener),new Slot(listener,name,at,finish,zone.getId(),zone.getRules().getOffset(at).getId(),rule,exception));}}
}
